from datetime import datetime
import pytz
from dateutil.parser import parse
from pytz.exceptions import AmbiguousTimeError, NonExistentTimeError


def _localize_safe(tz, dt):
    try:
        return tz.localize(dt, is_dst=None)
    except (AmbiguousTimeError, NonExistentTimeError):
        # Fallback for edge-case transition times.
        return tz.localize(dt, is_dst=False)


def task_func(date_str, tz_str):
    tz = pytz.timezone(tz_str)
    dt = parse(date_str)

    if dt.tzinfo is None:
        local_dt = _localize_safe(tz, dt)
    else:
        local_dt = dt.astimezone(tz)

    next_year_new_year = _localize_safe(
        tz, datetime(local_dt.year + 1, 1, 1, 0, 0, 0)
    )

    return int((next_year_new_year - local_dt).total_seconds())
